import { logger } from "../lib/logger.js"
// ─────────────────────────────────────────────────────────────────────────────
// routes/studentCertificates.ts — Student certificate routes at /api/student-certificates.
// Students check which subjects they've completed, claim a certificate, list
// their own certificates, and download the PDF generated by Puppeteer.
// ─────────────────────────────────────────────────────────────────────────────
import { Router, type Response } from "express"
import mongoose from "mongoose"
import { GridFSBucket } from "mongodb"
import { requireAuth, type AuthRequest } from "../middleware/auth.js"
import { User } from "../models/User.js"
import { Module } from "../models/Module.js"
import { ModuleProgress } from "../models/ModuleProgress.js"
import { Certificate } from "../models/Certificate.js"
import { CertTemplate } from "../models/CertTemplate.js"
import { School } from "../models/School.js"
import { generateCertificatePDF, fillDescription } from "../lib/pdf.js"

const router = Router()
router.use(requireAuth)

// ── GET /api/student-certificates/mine ───────────────────────────────────────
router.get("/mine", async (req: AuthRequest, res: Response) => {
  try {
    const studentId = new mongoose.Types.ObjectId(req.userId!)
    // Include school_id in the query to enforce school boundary.
    // Without it, a student whose account was moved between schools could see certs from the old school.
    const query: Record<string, unknown> = { student_id: studentId }
    if (req.schoolId) query.school_id = new mongoose.Types.ObjectId(req.schoolId)
    const certs = await Certificate.find(query).sort({ issued_at: -1 }).lean()
    res.json({ certificates: certs })
  } catch (err) {
    logger.error({ err: err }, "[student-certs mine]")
    res.status(500).json({ error: "Failed to load certificates" })
  }
})

// ── POST /api/student-certificates/claim ─────────────────────────────────────
// Student claims a subject completion certificate after finishing ALL modules in a subject
router.post("/claim", async (req: AuthRequest, res: Response) => {
  try {
    const studentId = new mongoose.Types.ObjectId(req.userId!)
    const student   = await User.findById(studentId).select("name school_id class_id").lean()
    if (!student?.school_id || !student?.class_id) {
      res.status(400).json({ error: "Student not in a class" }); return
    }

    const { subject } = req.body as { subject: string }
    if (!subject) { res.status(400).json({ error: "subject required" }); return }
    if (subject.length > 50) { res.status(400).json({ error: "Invalid subject" }); return }

    // Get all modules in this subject for the student's class
    const modulesInSubject = await Module.find({
      school_id: student.school_id,
      class_id:  student.class_id,
      subject,
    }).lean()

    if (modulesInSubject.length === 0) {
      res.status(404).json({ error: "No modules found for this subject" }); return
    }

    // Verify every item in every module has been viewed
    const allModuleIds = modulesInSubject.map(m => m._id)
    const viewedRecords = await ModuleProgress.find({
      student_id: studentId,
      module_id:  { $in: allModuleIds },
    }).lean()
    const viewedItemIds = new Set(viewedRecords.map(r => r.item_id.toString()))

    for (const mod of modulesInSubject) {
      if (mod.items.length === 0) {
        res.status(400).json({ error: `Module "${mod.title}" has no items` }); return
      }
      if (!mod.items.every(i => viewedItemIds.has(i._id.toString()))) {
        res.status(400).json({ error: `Complete all items in "${mod.title}" first` }); return
      }
    }

    // Get class label (needed for setOnInsert below)
    const ClassModel = mongoose.models.Class as mongoose.Model<{ grade: number; section: string; name?: string | null }> | undefined
    const cls = ClassModel ? await ClassModel.findById(student.class_id).select("grade section name").lean() : null
    const class_label = cls
      ? (cls.name ?? (cls.grade > 0 ? `Class ${cls.grade}${cls.section}` : cls.section))
      : "Class"

    // Atomic upsert — prevents duplicate certs from concurrent claims (race condition guard).
    // $setOnInsert only runs when a new document is inserted; if one already exists, it's returned as-is.
    const cert = await Certificate.findOneAndUpdate(
      { student_id: studentId, class_id: student.class_id, subject, type: "module" },
      { $setOnInsert: {
        school_id:    student.school_id,
        module_id:    null,
        module_title: subject,
        class_label,
        student_name: student.name,
        issued_at:    new Date(),
      }},
      { upsert: true, new: true }
    )

    res.json({ certificate: cert })
  } catch (err) {
    logger.error({ err: err }, "[student-certs claim]")
    res.status(500).json({ error: "Failed to claim certificate" })
  }
})

// ── GET /api/student-certificates/eligible ───────────────────────────────────
// Returns subjects where ALL modules are complete and no subject cert claimed yet
router.get("/eligible", async (req: AuthRequest, res: Response) => {
  try {
    const studentId = new mongoose.Types.ObjectId(req.userId!)
    const student   = await User.findById(studentId).select("school_id class_id").lean()
    if (!student?.class_id) { res.json({ eligible: [] }); return }

    const modules = await Module.find({
      school_id: student.school_id,
      class_id:  student.class_id,
    }).lean()

    if (modules.length === 0) { res.json({ eligible: [] }); return }

    const viewedRecords = await ModuleProgress.find({ student_id: studentId }).lean()
    const viewedItemIds = new Set(viewedRecords.map(r => r.item_id.toString()))

    // Subjects already certified
    const claimedCerts = await Certificate.find({ student_id: studentId, type: "module" }).lean()
    const claimedSubjects = new Set(claimedCerts.map(c => c.subject))

    // Group modules by subject, check all complete
    const subjectMap = new Map<string, { modules_count: number; total_items_count: number; all_complete: boolean }>()
    for (const mod of modules) {
      if (!subjectMap.has(mod.subject)) {
        subjectMap.set(mod.subject, { modules_count: 0, total_items_count: 0, all_complete: true })
      }
      const entry = subjectMap.get(mod.subject)!
      entry.modules_count++
      entry.total_items_count += mod.items.length
      if (mod.items.length === 0 || !mod.items.every(i => viewedItemIds.has(i._id.toString()))) {
        entry.all_complete = false
      }
    }

    const eligible = Array.from(subjectMap.entries())
      .filter(([subj, data]) => data.all_complete && !claimedSubjects.has(subj))
      .map(([subject, data]) => ({
        subject,
        modules_count:     data.modules_count,
        total_items_count: data.total_items_count,
      }))

    res.json({ eligible })
  } catch (err) {
    logger.error({ err: err }, "[student-certs eligible]")
    res.status(500).json({ error: "Failed to check eligibility" })
  }
})

// ── GET /api/student-certificates/download/:id ────────────────────────────────
// Student downloads their own certificate PDF (GridFS cached)
router.get("/download/:id", async (req: AuthRequest, res: Response) => {
  try {
    const studentId = new mongoose.Types.ObjectId(req.userId!)
    const cert = await Certificate.findById(req.params.id).lean()
    if (!cert) { res.status(404).json({ error: "Certificate not found" }); return }
    if (cert.student_id.toString() !== req.userId) { res.status(403).json({ error: "Forbidden" }); return }

    const db = mongoose.connection.db
    if (!db) throw new Error("DB not connected")
    const bucket = new GridFSBucket(db, { bucketName: "uploads" })

    const inline  = req.query.inline === "1"
    const safeName = cert.student_name.replace(/[^a-z0-9]/gi, "_").toLowerCase()
    const disposition = inline
      ? `inline; filename="Certificate_${safeName}.pdf"`
      : `attachment; filename="Certificate_${safeName}.pdf"`

    // Serve from GridFS cache if available
    if (cert.pdf_gridfs_id) {
      try {
        const files = await bucket.find({ _id: cert.pdf_gridfs_id }).toArray()
        if (files.length > 0) {
          res.setHeader("Content-Type", "application/pdf")
          res.setHeader("Content-Disposition", disposition)
          bucket.openDownloadStream(cert.pdf_gridfs_id).pipe(res)
          return
        }
      } catch { /* fall through */ }
    }

    // Generate fresh
    const school = await School.findById(cert.school_id).lean()
    let tmpl = await CertTemplate.findOne({ school_id: cert.school_id }).lean()
    if (!tmpl) {
      const created = await CertTemplate.create({ school_id: cert.school_id, school_name: school?.name ?? "School" })
      tmpl = created.toObject()
    }
    if (!tmpl) { res.status(500).json({ error: "Failed to load certificate template" }); return }

    // Fetch logo if stored
    let logoB64: string | undefined; let logoMime: string | undefined
    if (tmpl.logo_gridfs_id) {
      try {
        const chunks: Buffer[] = []
        await new Promise<void>((resolve, reject) => {
          const s = bucket.openDownloadStream(tmpl!.logo_gridfs_id!)
          s.on("data", c => chunks.push(c as Buffer)); s.on("end", resolve); s.on("error", reject)
        })
        const files = await bucket.find({ _id: tmpl.logo_gridfs_id }).toArray()
        logoB64  = Buffer.concat(chunks).toString("base64")
        logoMime = (files[0] as unknown as { contentType?: string }).contentType ?? "image/png"
      } catch { /* no logo */ }
    }

    const isCustom    = cert.type === "custom"
    const displayTitle   = isCustom ? cert.custom_title : cert.module_title
    const displaySubject = isCustom ? cert.custom_reason : cert.subject

    const description = isCustom
      ? (cert.custom_reason ?? "")
      : fillDescription(tmpl.description, {
          module_title: cert.module_title, subject: cert.subject,
          class_label: cert.class_label, student_name: cert.student_name,
          school_name: tmpl.school_name,
        })

    const pdfTemplate = (() => {
      if (!isCustom) return "completion"
      if (cert.cert_template === "outstanding_achievement") return "outstanding_achievement"
      return "default"
    })()

    const pdfBuf = await generateCertificatePDF({
      student_name:   cert.student_name,
      module_title:   displayTitle,
      subject:        displaySubject,
      class_label:    cert.class_label,
      school_name:    tmpl.school_name,
      logo_base64:    logoB64,
      logo_mime:      logoMime,
      description,
      footer_left:    tmpl.footer_left,
      footer_right:   tmpl.footer_right,
      accent_color:   tmpl.accent_color,
      date:           new Date(cert.issued_at).toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" }),
      cert_title:     isCustom ? cert.custom_title : undefined,
      cert_subtitle:  isCustom ? "Special Award" : undefined,
      template:       pdfTemplate as "completion" | "default" | "outstanding_achievement",
    })

    // Cache in GridFS
    const newId = new mongoose.Types.ObjectId()
    const str   = bucket.openUploadStreamWithId(newId, `cert_${cert._id}.pdf`, { metadata: { contentType: "application/pdf" } })
    str.write(pdfBuf); str.end()
    await new Promise<void>((resolve, reject) => { str.on("finish", resolve); str.on("error", reject) })
    await Certificate.findByIdAndUpdate(cert._id, { pdf_gridfs_id: newId })

    res.setHeader("Content-Type", "application/pdf")
    res.setHeader("Content-Disposition", disposition)
    res.send(pdfBuf)
  } catch (err) {
    logger.error({ err: err }, "[student-cert download]")
    res.status(500).json({ error: "Failed to generate certificate" })
  }
})

export default router
